export const PHASE_LABELS=Object.freeze({preroll:'先聽音樂',question:'先看方向',demonstrate:'看示範，聽節拍',countdown:'準備，四拍後開始',input:'跟上節拍','round-result':'這一題的回饋',sync:'聽拍，下一小節開始',complete:'Dance 完成'});
export function dancePresentation(dance,mapId){const p=dance.phase.phase,remaining=Math.max(1,Math.ceil((dance.prerollMs-dance.clockMs)/500));return {phase:p,title:PHASE_LABELS[p]??'',difficulty:mapId===4?'ADVANCED':'BEGINNER',round:`${mapId===4?'ROUND':'STAGE'} ${dance.stage.id} / ${mapId===4?6:3}`,count:p==='preroll'?String(Math.min(8,remaining)):p==='countdown'?String(dance.phase.countInValue):'',intro:p==='preroll'||p==='countdown',introLit:p==='preroll'?Math.max(0,9-Math.min(9,remaining)):5-dance.phase.countInValue,showSequence:p!=='preroll',active:p==='demonstrate'?dance.phase.demoIndex:p==='input'?dance.phase.inputIndex:-1,feedback:['round-result','sync','complete'].includes(p)?dance.feedback:null};}

export function renderStudioDance(dance,mapId,audioStatus){const $=id=>document.getElementById(id),v=dancePresentation(dance,mapId),root=$('dancePanel'),list=$('danceCells'),arrows={left:'←',up:'↑',down:'↓',right:'→'};root.dataset.phase=v.phase;
 $('danceModeLabel').textContent=v.difficulty;$('danceStage').textContent=v.round;$('dancePhase').textContent=v.title;$('danceStepCount').textContent=dance.stage.sequence.length+' STEPS';$('danceCount').textContent=v.count;list.hidden=!v.showSequence;
 if(list.children.length!==dance.stage.sequence.length)list.replaceChildren(...dance.stage.sequence.map((_,i)=>{const cell=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small'),idx=document.createElement('span');idx.className='index';idx.textContent=String(i+1).padStart(2,'0');cell.append(idx,b,small);return cell}));
 [...list.children].forEach((cell,i)=>{const outcome=dance.cells[i];cell.className=`cue ${outcome} ${i===v.active?'active':''}`;cell.querySelector('b').textContent=arrows[dance.stage.sequence[i]];cell.querySelector('small').textContent=({correct:'✓',wrong:'×',miss:'—'})[outcome]??'';cell.setAttribute('aria-label',`第${i+1}拍 ${arrows[dance.stage.sequence[i]]} ${outcome}`)});
 const lamps=$('danceIntroBeats'),n=v.phase==='preroll'?8:4;lamps.hidden=!v.intro;if(v.intro){if(lamps.children.length!==n)lamps.replaceChildren(...Array.from({length:n},()=>document.createElement('i')));const on=v.introLit;[...lamps.children].forEach((el,i)=>el.classList.toggle('on',i<on));}
 let feedback=root.querySelector('.dance-feedback');if(!feedback){feedback=document.createElement('div');feedback.className='dance-feedback';feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');feedback.innerHTML='<strong></strong><span></span><small></small>';root.querySelector('.readout').append(feedback);}feedback.hidden=!v.feedback;if(v.feedback){feedback.dataset.outcome=v.feedback.outcome;for(const [tag,text]of [['strong',v.feedback.title],['span',v.feedback.detail],['small',dance.stageIndex===dance.stages.length-1?'準備完成舞會':'稍等一下，下一題跟著音樂開始']]){const el=feedback.querySelector(tag);if(el.textContent!==text)el.textContent=text;}}
 const blocked=['blocked','error','resume-blocked'].includes(audioStatus);$('audioRetry').hidden=!blocked;$('audioRetry').textContent=audioStatus==='resume-blocked'?'繼續舞會音訊':'重試音訊';$('danceAudioStatus').textContent=blocked?'等待音訊':'方向鍵 / WASD';
}
export function bindDanceSwipe(element,onDirection){let start=null;const down=e=>{if(e.target.closest('button'))return;start={x:e.clientX,y:e.clientY,id:e.pointerId};element.setPointerCapture?.(e.pointerId)},up=e=>{if(!start||start.id!==e.pointerId)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;onDirection(Math.abs(dx)>Math.abs(dy)?dx<0?'left':'right':dy<0?'up':'down')},cancel=()=>{start=null};element.addEventListener('pointerdown',down);element.addEventListener('pointerup',up);element.addEventListener('pointercancel',cancel);return ()=>{element.removeEventListener('pointerdown',down);element.removeEventListener('pointerup',up);element.removeEventListener('pointercancel',cancel)};}
